import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as n,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Agentic Engineering Patterns","description":"","frontmatter":{},"headers":[],"relativePath":"zh/tech/patterns/agent/agentic-engineering-patterns.md","filePath":"zh/tech/patterns/agent/agentic-engineering-patterns.md","lastUpdated":1786817277000}'),i={name:"zh/tech/patterns/agent/agentic-engineering-patterns.md"};function o(l,e,s,h,g,d){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="agentic-engineering-patterns" tabindex="-1">Agentic Engineering Patterns <a class="header-anchor" href="#agentic-engineering-patterns" aria-label="Permalink to &quot;Agentic Engineering Patterns&quot;">​</a></h1><blockquote><p>原文：<a href="https://simonwillison.net/guides/agentic-engineering-patterns/" target="_blank" rel="noreferrer">Agentic Engineering Patterns</a> — Simon Willison</p></blockquote><h2 id="什么是-agentic-engineering" tabindex="-1">什么是 Agentic Engineering <a class="header-anchor" href="#什么是-agentic-engineering" aria-label="Permalink to &quot;什么是 Agentic Engineering&quot;">​</a></h2><p><strong>Agentic engineering</strong>：在编码 Agent（如 Claude Code、OpenAI Codex、Gemini CLI）辅助下开发软件的技术。</p><h3 id="agent-的定义" tabindex="-1">Agent 的定义 <a class="header-anchor" href="#agent-的定义" aria-label="Permalink to &quot;Agent 的定义&quot;">​</a></h3><blockquote><p>Agents run tools in a loop to achieve a goal.</p></blockquote><p>Agent 是软件，它调用 LLM，传入 Prompt 和工具定义，LLM 请求什么工具就执行什么工具，然后把结果反馈给 LLM。对于编码 Agent，那些工具包含<strong>执行代码的能力</strong>。</p><p><strong>代码执行是让 Agentic Engineering 成为可能的关键能力。</strong> 没有直接运行代码的能力，LLM 输出的任何东西价值都有限。有了代码执行，Agent 才能开始迭代，直到产出能工作的软件。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="llm-大语言模型" tabindex="-1">LLM = 大语言模型 <a class="header-anchor" href="#llm-大语言模型" aria-label="Permalink to &quot;LLM = 大语言模型&quot;">​</a></h3><ul><li>输入是 <strong>Prompt</strong>，输出是 <strong>Completion/Response</strong></li><li>工作在 <strong>Token</strong> 层面（文本转为整数序列），按 Token 计费</li><li>多模态：可以接受图像作为输入，图像也会转为 Token 整数处理</li></ul><h3 id="chat-模板-prompt" tabindex="-1">Chat 模板 Prompt <a class="header-anchor" href="#chat-模板-prompt" aria-label="Permalink to &quot;Chat 模板 Prompt&quot;">​</a></h3><p>LLM 本质是无状态的，每次执行 Prompt 都是从空白 slate 开始。需要聊天软件自己维护状态，重放整个对话历史。</p><h3 id="token-缓存" tabindex="-1">Token 缓存 <a class="header-anchor" href="#token-缓存" aria-label="Permalink to &quot;Token 缓存&quot;">​</a></h3><p>模型提供商对缓存的输入 Token 提供更便宜的费率。编码 Agent 设计时会避免修改早期对话内容，以最大化缓存效率。</p><h3 id="工具调用" tabindex="-1">工具调用 <a class="header-anchor" href="#工具调用" aria-label="Permalink to &quot;工具调用&quot;">​</a></h3><p>Agent 调用工具时，Prompt 里会包含工具定义，LLM 输出类似 <code>&lt;tool&gt;get_weather(&quot;San Francisco&quot;)&lt;/tool&gt;</code> 的文本，Harness 用正则提取并执行工具。</p><p>编码 Agent 通常定义十几个工具，最强大的是允许代码执行的工具：Bash() 执行终端命令、Python() 运行 Python 代码。</p><h3 id="system-prompt" tabindex="-1">System Prompt <a class="header-anchor" href="#system-prompt" aria-label="Permalink to &quot;System Prompt&quot;">​</a></h3><p>编码 Agent 在每次对话开始时都会注入 System Prompt，告诉模型如何行为。这些 Prompt 可能长达数百行。OpenAI Codex 的 System Prompt 是很好的参考例子。</p><h3 id="推理-reasoning" tabindex="-1">推理（Reasoning） <a class="header-anchor" href="#推理-reasoning" aria-label="Permalink to &quot;推理（Reasoning）&quot;">​</a></h3><p>2025 年的大突破：推理能力。模型在正式回复前，先生成&quot;思考&quot;文本来展开问题和解法。推理对调试特别有用，让模型有机会混合工具调用和函数追踪。</p><h2 id="核心模式" tabindex="-1">核心模式 <a class="header-anchor" href="#核心模式" aria-label="Permalink to &quot;核心模式&quot;">​</a></h2><h3 id="_1-red-green-tdd" tabindex="-1">1. Red/Green TDD <a class="header-anchor" href="#_1-red-green-tdd" aria-label="Permalink to &quot;1. Red/Green TDD&quot;">​</a></h3><p>先写测试再写代码。Agent 可以自动化这个循环。</p><h3 id="_2-first-run-the-tests" tabindex="-1">2. First Run the Tests <a class="header-anchor" href="#_2-first-run-the-tests" aria-label="Permalink to &quot;2. First Run the Tests&quot;">​</a></h3><p>让 Agent 先运行测试，理解现有代码行为。</p><h3 id="_3-agentic-manual-testing" tabindex="-1">3. Agentic Manual Testing <a class="header-anchor" href="#_3-agentic-manual-testing" aria-label="Permalink to &quot;3. Agentic Manual Testing&quot;">​</a></h3><p>Agent 做人工测试时，可以用浏览器自动化测试 Web UI，或者用 Showboat 做笔记。</p><h3 id="_4-subagents" tabindex="-1">4. Subagents <a class="header-anchor" href="#_4-subagents" aria-label="Permalink to &quot;4. Subagents&quot;">​</a></h3><p>Claude Code 的 Explore 子 Agent、并行子 Agent、专家型子 Agent。</p><h3 id="_5-linear-walkthroughs" tabindex="-1">5. Linear Walkthroughs <a class="header-anchor" href="#_5-linear-walkthroughs" aria-label="Permalink to &quot;5. Linear Walkthroughs&quot;">​</a></h3><p>线性通读代码，配合 Showboat 和 Present 使用。</p><h3 id="_6-interactive-explanations" tabindex="-1">6. Interactive Explanations <a class="header-anchor" href="#_6-interactive-explanations" aria-label="Permalink to &quot;6. Interactive Explanations&quot;">​</a></h3><p>交互式解释，理解词云等可视化内容。</p><h2 id="反模式-anti-patterns" tabindex="-1">反模式（Anti-patterns） <a class="header-anchor" href="#反模式-anti-patterns" aria-label="Permalink to &quot;反模式（Anti-patterns）&quot;">​</a></h2><h3 id="不要做-inflicting-unreviewed-code-on-collaborators" tabindex="-1">不要做：Inflicting unreviewed code on collaborators <a class="header-anchor" href="#不要做-inflicting-unreviewed-code-on-collaborators" aria-label="Permalink to &quot;不要做：Inflicting unreviewed code on collaborators&quot;">​</a></h3><p>未经审查的代码会给协作者带来麻烦。Agentic engineering 应该产出经过验证的、达到生产标准的代码，而不仅仅是&quot;能跑&quot;的代码。</p><h2 id="与-vibe-coding-的区别" tabindex="-1">与 Vibe Coding 的区别 <a class="header-anchor" href="#与-vibe-coding-的区别" aria-label="Permalink to &quot;与 Vibe Coding 的区别&quot;">​</a></h2><p><strong>Vibe coding</strong>（Andrej Karpathy 2025年2月提出）：prompt LLM 写代码时&quot;忘记代码的存在&quot;。</p><p>Agentic engineering 不是 vibe coding。区别在于：</p><ul><li>Vibe coding：未经审查、原型质量的 LLM 生成代码</li><li>Agentic engineering：需要验证和迭代，确保产出可靠</li></ul><h2 id="关键洞见" tabindex="-1">关键洞见 <a class="header-anchor" href="#关键洞见" aria-label="Permalink to &quot;关键洞见&quot;">​</a></h2><ol><li><strong>写代码现在很便宜</strong> — 难点在于搞清楚写什么代码</li><li><strong>需要建立新习惯</strong> — 积累自己的&quot;工具箱&quot;并学会重组</li><li><strong>AI 应该帮助我们产出更好的代码</strong> — 而不只是更多代码</li><li><strong>拥抱复合工程循环</strong> — 不断迭代改进</li></ol><h2 id="对前端-ai-学习的启发" tabindex="-1">对前端 AI 学习的启发 <a class="header-anchor" href="#对前端-ai-学习的启发" aria-label="Permalink to &quot;对前端 AI 学习的启发&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>前端场景</th></tr></thead><tbody><tr><td>Red/Green TDD</td><td>Vitest + Playwright E2E</td></tr><tr><td>Subagents</td><td>Cursor 多 Agent 协作</td></tr><tr><td>Token 缓存优化</td><td>控制 Prompt 长度</td></tr><tr><td>System Prompt 工程</td><td>Cursor Rules 编写</td></tr><tr><td>Reasoning 调优</td><td>Claude Code 思考深度配置</td></tr></tbody></table>',46)])])}const q=t(i,[["render",o]]);export{m as __pageData,q as default};
